rules.InvariantScript:
If(
    !varScanAccepted,
    If(
        IsEmpty(Self.Results),
        Set(varOcrEmpty, true),
        Set(varScanAccepted, true);
        Set(varOcrEmpty, false);
        Set(
            varAcceptedText,
            First(
                Sort(
                    Self.Results,
                    BoundingBox.Top,
                    SortOrder.Ascending
                )
            ).Text
        );
        Navigate(scrLoading, ScreenTransition.Fade);
        IfError(
            barcode_flow.Run(varAcceptedText),
            Set(varErrorMessage, "Stok bilgileri alınırken bir bağlantı hatası oluştu.");
            Navigate(scrError, ScreenTransition.Fade)
        )
    )
)

